import sys
sys.setrecursionlimit(5000)

def findConnections(i, j, visited, connections):
	if i > 0:
		if visited[i - 1][j] == False:
			connections[-1].append(land[i - 1][j])
			visited[i - 1][j] = True
			findConnections(i - 1, j, visited, connections)
	if i < N - 1:
		if visited[i + 1][j] == False:
			connections[-1].append(land[i + 1][j])
			visited[i + 1][j] = True
			findConnections(i + 1, j, visited, connections)
	if j > 0:
		if visited[i][j - 1] == False:
			connections[-1].append(land[i][j - 1])
			visited[i][j - 1] = True
			findConnections(i, j - 1, visited, connections)
	if j < N - 1:
		if visited[i][j + 1] == False:
			connections[-1].append(land[i][j + 1])
			visited[i][j + 1] = True
			findConnections(i, j + 1, visited, connections)

def countAns(connections):
	ans = 1
	for i in connections:
		if len(i) == 1 and i == ['?']:
			ans = ans % MOD * 3
		if len(i) > 1:
			if i.count('G') > 0:
				ans = 0
				break
			elif i.count('B') > 0 and i.count('P') > 0:
				ans = 0
				break
			elif i.count('B') > 0 or i.count('P') > 0:
				ans *= 1
			else:
				ans = ans % MOD * 2
	return ans % MOD

def solve(N, land):
	visited = [[True if land[i][j] == '.' else False for j in range(N)] for i in range(N)]
	connections = []
	for i in range(N):
		for j in range(N):
			if visited[i][j] == False:
				visited[i][j] = True
				connections.append([land[i][j]])
				findConnections(i, j, visited, connections)
	ans = countAns(connections)
	return ans
T = int(input())
for case in range(1, T + 1):
	N = int(input())
	land = [[i for i in input()] for j in range(N)]
	MOD = 10 ** 9 + 7
	print(solve(N, land))
